// Ночник с датчиком движения: XIAO ESP32-C3
// PIR PIR223D-S0 (REL -> D1), свет BH1750 (I2C SDA/SCL), 4 тёплых LED через NPN (база -> D10), кнопка режима (D2 -> GND)
// Логика: темно (<15 лк) + движение = плавное включение на 30 с; кнопка = авто / постоянный слабый свет
#include <Wire.h>

#define PIR_PIN 3    // D1 = GPIO3
#define LED_PIN 10   // D10 = GPIO10
#define BTN_PIN 4    // D2 = GPIO4

#define BH_ADDR 0x23
#define LUX_DARK 15.0f
#define LUX_LIGHT 25.0f
#define LIGHT_TIME_MS 30000UL
#define FADE_MS 1200

bool alwaysOn = false;
bool lampOn = false;
unsigned long lampUntil = 0;
unsigned long fadeStart = 0;
bool fadingIn = false;
int bright = 0;
const int BRIGHT_FULL = 3800;
const int BRIGHT_NIGHT = 1200;
bool darkLatch = true;
float lux = 0;
unsigned long lastLux = 0;
int lastBtn = HIGH;
unsigned long bootAt = 0;

float readLux() {
  Wire.beginTransmission(BH_ADDR);
  Wire.write(0x01);
  if (Wire.endTransmission() != 0) return -1;
  Wire.beginTransmission(BH_ADDR);
  Wire.write(0x10);
  if (Wire.endTransmission() != 0) return -1;
  delay(180);
  Wire.requestFrom(BH_ADDR, 2);
  if (Wire.available() < 2) return -1;
  uint16_t raw = (Wire.read() << 8) | Wire.read();
  return raw / 1.2f;
}

void setLamp(bool on) {
  lampOn = on;
  fadeStart = millis();
  fadingIn = on;
}

void setup() {
  pinMode(PIR_PIN, INPUT);
  pinMode(BTN_PIN, INPUT_PULLUP);
  ledcAttach(LED_PIN, 5000, 12);
  ledcWrite(LED_PIN, 0);
  Wire.begin();
  Serial.begin(115200);
  delay(500);
  float l = readLux();
  if (l >= 0) { lux = l; darkLatch = (lux < LUX_DARK); }
  else darkLatch = true;
  bootAt = millis();
}

void loop() {
  unsigned long now = millis();
  bool warmed = (now - bootAt > 30000UL); // прогрев PIR ~30 с: движение игнорируем
  if (now - lastLux > 1000) {
    lastLux = now;
    float l = readLux();
    if (l >= 0) {
      lux = l;
      if (lux < LUX_DARK) darkLatch = true;
      else if (lux > LUX_LIGHT) darkLatch = false;
    }
  }
  int b = digitalRead(BTN_PIN);
  if (b != lastBtn) {
    delay(50);
    b = digitalRead(BTN_PIN);
    if (b != lastBtn) {
      if (lastBtn == LOW && b == HIGH) { alwaysOn = !alwaysOn; if (alwaysOn) setLamp(true); else setLamp(false); }
      lastBtn = b;
    }
  }
  if (alwaysOn) {
    if (bright < BRIGHT_NIGHT) bright = min(BRIGHT_NIGHT, bright + 40);
    if (bright > BRIGHT_NIGHT) bright = max(BRIGHT_NIGHT, bright - 40);
    ledcWrite(LED_PIN, bright);
    lampOn = true;
    return;
  }
  int motion = warmed ? digitalRead(PIR_PIN) : LOW;
  if (motion == HIGH && darkLatch) { lampUntil = now + LIGHT_TIME_MS; if (!lampOn) setLamp(true); }
  if (lampOn && now > lampUntil && motion == LOW) setLamp(false);
  if (lampOn && !darkLatch && !alwaysOn) setLamp(false);
  unsigned long fe = now - fadeStart;
  if (fadingIn) bright = min(BRIGHT_FULL, (int)(BRIGHT_FULL * min(1.0f, fe / (float)FADE_MS)));
  else bright = max(0, (int)(BRIGHT_FULL * (1.0f - min(1.0f, fe / (float)FADE_MS))));
  if (!lampOn && fe > FADE_MS) bright = 0;
  ledcWrite(LED_PIN, bright);
  delay(20);
}
